import { Themes } from "@csc/common";
function themeToCDOTheme(theme) {
    switch(theme){
        case 'darkest':
            return Themes.darkest;
        case 'dark':
            return Themes.dark;
        case 'lightest':
            return Themes.lightest;
        case 'light':
        default:
            return Themes.light;
    }
}
export { themeToCDOTheme };
